async (page) => {
  const crypto = require('crypto');
  const S = '/private/tmp/claude/claude-502/-Users-kenneth--claude-spares-spare-sN2SQi/dfe4dcbb-035f-4143-8606-810d508fc78c/scratchpad/css-refactor/';
  const browser = page.context().browser();
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 }, deviceScaleFactor: 1 });
  const p = await ctx.newPage();
  const hash = (buf) => crypto.createHash('sha1').update(buf).digest('hex');
  const out = {};
  // The add-printer form's two screens, whole page.
  for (const name of ['form-filaments', 'form-nearby']) {
    const shots = {};
    for (const side of ['before', 'after']) {
      await p.goto(`http://127.0.0.1:8795/${side}/${name}.html`);
      await p.waitForTimeout(300);
      const captions = await p.locator(side === 'before' ? '.printer-form-section, .printer-form-heading' : '.section-caption').evaluateAll((els) => els.map((el) => { const cs = getComputedStyle(el); return [el.textContent, cs.fontSize, cs.fontWeight, cs.textTransform, cs.color, cs.padding, cs.flex].join(' | '); }));
      const buf = await p.screenshot({ fullPage: true, path: `${S}${side}-${name}.png` });
      shots[side] = { hash: hash(buf), captions };
    }
    out[name] = { samePixels: shots.before.hash === shots.after.hash, captionsBefore: shots.before.captions, sameCaptions: JSON.stringify(shots.before.captions) === JSON.stringify(shots.after.captions) };
  }
  // Every figure of the review page that holds a menu caption.
  const figs = {};
  for (const side of ['before', 'after']) {
    await p.goto(`http://127.0.0.1:8795/${side}.html`);
    await p.waitForTimeout(800);
    const sel = side === 'before' ? '.chat-menu-section' : '.section-caption';
    const figures = p.locator('figure', { has: p.locator(sel) });
    const n = await figures.count();
    const list = [];
    for (let i = 0; i < n; i++) {
      const f = figures.nth(i);
      const id = await f.evaluate((el) => `${el.dataset.case}/${el.dataset.mode}/${el.dataset.dock}`);
      list.push([id, hash(await f.screenshot())]);
    }
    figs[side] = list;
  }
  const diff = figs.before.filter(([id, h], i) => !figs.after[i] || figs.after[i][0] !== id || figs.after[i][1] !== h).map(([id]) => id);
  out.reviewPage = { figuresBefore: figs.before.length, figuresAfter: figs.after.length, figuresThatDiffer: diff, ids: [...new Set(figs.before.map(([id]) => id.split('/')[0]))] };
  await ctx.close();
  return out;
}

